def env_lines(text):
    result = {}

    for line in text.splitlines():
        stripped = line.strip()

        if not stripped or stripped.startswith("#"):
            continue

        if "=" not in stripped:
            raise ValueError("Missing '=' in environment variable line")

        key, _, value = stripped.partition("=")
        key = key.strip()
        value = value.strip()

        if key == "":
            raise ValueError("Empty environment variable key")

        result[key] = value

    return result

def reconcile(desired, actual):
    def equal(a, b):
        if isinstance(a, bool) or isinstance(b, bool):
            return isinstance(a, bool) and isinstance(b, bool) and a == b

        if isinstance(a, dict) and isinstance(b, dict):
            if a.keys() != b.keys():
                return False
            for key, value in a.items():
                if not equal(value, b[key]):
                    return False
            return True

        if isinstance(a, list) and isinstance(b, list):
            if len(a) != len(b):
                return False
            return all(equal(left, right) for left, right in zip(a, b))

        return a == b

    common = set(desired) & set(actual)
    create = sorted(set(desired) - set(actual))
    delete = sorted(set(actual) - set(desired))
    update = sorted(name for name in common if not equal(desired[name], actual[name]))

    return {
        "create": create,
        "update": update,
        "delete": delete,
    }

def changed_paths(before, after):
    def walk(b, a, prefix):
        paths = []

        if isinstance(b, dict) and isinstance(a, dict):
            for key in set(b) & set(a):
                vb, va = b[key], a[key]
                if vb == va:
                    continue

                full = key if prefix == "" else prefix + "." + key

                if isinstance(vb, dict) and isinstance(va, dict):
                    paths.extend(walk(vb, va, full))
                else:
                    paths.append(full)

            for key in set(b) - set(a):
                full = key if prefix == "" else prefix + "." + key
                paths.append(full)

            for key in set(a) - set(b):
                full = key if prefix == "" else prefix + "." + key
                paths.append(full)

        elif b != a:
            paths.append(prefix)

        return paths

    return sorted(set(walk(before, after, "")))

def coalesce(intervals):
    normalized = []

    for interval in intervals:
        start, end = interval

        if start > end:
            raise ValueError("start must be less than or equal to end")

        if start == end:
            continue

        normalized.append((start, end))

    merged = []

    for start, end in sorted(normalized):
        if not merged:
            merged.append((start, end))
        elif start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    return merged

