def unique_latest(records):
    latest = {}
    for record in records:
        record_id = record["id"]
        timestamp = record["timestamp"]

        if record_id not in latest or timestamp >= latest[record_id]["timestamp"]:
            latest[record_id] = record

    return list(latest.values())

from bisect import bisect_right

def histogram(edges, values):
    if not isinstance(edges, list) or len(edges) < 2:
        raise ValueError("edges must be a list with at least two numbers")

    for i in range(1, len(edges)):
        if not (edges[i - 1] < edges[i]):
            raise ValueError("edges must be strictly increasing")

    counts = [0] * (len(edges) - 1)
    first = edges[0]
    last = edges[-1]

    for value in values:
        if value < first or value > last:
            continue

        pos = bisect_right(edges, value)
        if pos == len(edges):
            if value == last:
                counts[-1] += 1
        else:
            counts[pos - 1] += 1

    return counts
